arduino.setup:
Serial.begin(115200);
pinMode(${DO}, INPUT);
Serial.println("MQ-2 Gas Sensor ready.");

arduino.loop:
int analogVal = analogRead(${AO});
int digitalVal = digitalRead(${DO});
Serial.print("MQ-2 AO: ");
Serial.print(analogVal);
Serial.print("  DO: ");
Serial.println(digitalVal == LOW ? "GAS DETECTED" : "Clear");
delay(1000);
